def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same well-formed-pair search as :func:`upsert_metadata_block`, so
    the reader and the writer agree on which block is authoritative. A quoted
    example elsewhere in the body — an unfinished BEGIN with no matching END,
    before or after the real block — is not a block at all and must not leak
    fields like `parent` into the parsed result.
    """
    if not body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
